const fs = require('fs');
const path = require('path');

// Ensure production HTML has correct icon references
const htmlPath = path.join(__dirname, 'dist', 'public', 'index.html');
if (fs.existsSync(htmlPath)) {
  let html = fs.readFileSync(htmlPath, 'utf8');

  // Check if already has precomposed icons
  if (!html.includes('apple-touch-icon-precomposed')) {
    // Replace the Apple touch icon section
    const oldSection = `  <!-- Apple Touch Icons for iOS -->
  <link rel="apple-touch-icon" sizes="180x180" href="/icons/apple-touch-icon-180x180.png" />
  <link rel="apple-touch-icon" sizes="152x152" href="/icons/apple-touch-icon-152x152.png" />
  <link rel="apple-touch-icon" sizes="120x120" href="/icons/apple-touch-icon-120x120.png" />`;

    const newSection = `  <!-- Apple Touch Icons for iOS - Precomposed first for better compatibility -->
  <link rel="apple-touch-icon-precomposed" href="/apple-touch-icon-precomposed.png?v=1.4" />
  <link rel="apple-touch-icon" href="/apple-touch-icon.png?v=1.4" />
  <link rel="apple-touch-icon-precomposed" sizes="152x152" href="/apple-touch-icon-152x152-precomposed.png?v=1.4" />
  <link rel="apple-touch-icon-precomposed" sizes="120x120" href="/apple-touch-icon-120x120-precomposed.png?v=1.4" />
  <link rel="apple-touch-icon-precomposed" sizes="76x76" href="/apple-touch-icon-76x76-precomposed.png?v=1.4" />
  <link rel="apple-touch-icon" sizes="192x192" href="/apple-touch-icon-192x192.png?v=1.4" />
  <link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon-180x180.png?v=1.4" />
  <link rel="apple-touch-icon" sizes="152x152" href="/apple-touch-icon-152x152.png?v=1.4" />
  <link rel="apple-touch-icon" sizes="120x120" href="/apple-touch-icon-120x120.png?v=1.4" />
  <link rel="apple-touch-icon" sizes="76x76" href="/apple-touch-icon-76x76.png?v=1.4" />
  <link rel="apple-touch-icon" sizes="60x60" href="/apple-touch-icon-60x60.png?v=1.4" />`;

    html = html.replace(oldSection, newSection);
    fs.writeFileSync(htmlPath, html);
    console.log('✅ Production HTML updated with correct icon references');
  }
}

// Copy all icon files to production
const srcIconsDir = path.join(__dirname, 'public');
const destIconsDir = path.join(__dirname, 'dist', 'public');

if (fs.existsSync(destIconsDir)) {
  // Copy Apple touch icons
  const iconFiles = fs.readdirSync(srcIconsDir).filter(f => f.startsWith('apple-touch-icon'));
  iconFiles.forEach(file => {
    const src = path.join(srcIconsDir, file);
    const dest = path.join(destIconsDir, file);
    fs.copyFileSync(src, dest);
  });

  // Ensure icons folder exists
  const destIconsFolder = path.join(destIconsDir, 'icons');
  if (!fs.existsSync(destIconsFolder)) {
    fs.mkdirSync(destIconsFolder);
  }

  // Copy all icons to icons folder
  const iconsFolder = path.join(srcIconsDir, 'icons');
  if (fs.existsSync(iconsFolder)) {
    const icons = fs.readdirSync(iconsFolder).filter(f => f.endsWith('.png'));
    icons.forEach(file => {
      const src = path.join(iconsFolder, file);
      const dest = path.join(destIconsFolder, file);
      fs.copyFileSync(src, dest);
    });
  }

  // Copy manifest and favicon
  ['manifest.json', 'favicon.ico'].forEach(file => {
    const src = path.join(srcIconsDir, file);
    const dest = path.join(destIconsDir, file);
    if (fs.existsSync(src)) {
      fs.copyFileSync(src, dest);
    }
  });

  console.log(`✅ Copied ${iconFiles.length} Apple touch icons to production`);
}

sw.js.content:
// Bytewise Nutrition Tracker - Service Worker
// Provides offline functionality and caching for PWA experience

const CACHE_NAME = 'bytewise-v3.0';
const STATIC_CACHE = 'bytewise-static-v5';
const DYNAMIC_CACHE = 'bytewise-dynamic-v5';
const API_CACHE = 'bytewise-api-v5';
const ICON_CACHE = 'bytewise-icons-v3';

// Critical resources to cache immediately
const STATIC_ASSETS = [
  '/',
  '/index.html',
  '/manifest.json?v=3.0',
  '/apple-icon.png',
  '/apple-touch-icon.png',
  '/icons/icon-192x192.png',
  '/icons/icon-512x512.png'
];

// API endpoints to cache for offline functionality
const API_ENDPOINTS = [
  '/api/auth/user',
  '/api/version',
  '/api/foods',
  '/api/usda/search'
];

// Install event - cache static assets
self.addEventListener('install', event => {
  console.log('🔧 Service Worker installing...');

  event.waitUntil(
    caches.open(STATIC_CACHE)
      .then(cache => {
        console.log('📦 Caching static assets');
        return cache.addAll(STATIC_ASSETS);
      })
      .then(() => {
        console.log('✅ Static assets cached successfully');
        return self.skipWaiting();
      })
      .catch(err => {
        console.error('❌ Failed to cache static assets:', err);
      })
  );
});

// Listen for skip waiting message
self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    console.log('⏩ Received SKIP_WAITING, activating new service worker');
    self.skipWaiting();
  }
});

// Activate event - clean up old caches
self.addEventListener('activate', event => {
  console.log('🚀 Service Worker activating...');

  event.waitUntil(
    caches.keys()
      .then(cacheNames => {
        return Promise.all(
          cacheNames
            .filter(cacheName => {
              return cacheName !== STATIC_CACHE && 
                     cacheName !== DYNAMIC_CACHE && 
                     cacheName !== API_CACHE &&
                     cacheName !== ICON_CACHE;
            })
            .map(cacheName => {
              console.log('🗑️ Deleting old cache:', cacheName);
              return caches.delete(cacheName);
            })
        );
      })
      .then(() => {
        console.log('✅ Service Worker activated');
        return self.clients.claim();
      })
  );
});

// Fetch event - implement caching strategies
self.addEventListener('fetch', event => {
  const { request } = event;
  const url = new URL(request.url);

  // Skip non-GET requests
  if (request.method !== 'GET') {
    return;
  }

  // Handle API requests
  if (url.pathname.startsWith('/api/')) {
    event.respondWith(handleApiRequest(request));
    return;
  }

  // Handle static assets
  if (STATIC_ASSETS.some(asset => url.pathname === asset || url.pathname.endsWith(asset))) {
    event.respondWith(handleStaticRequest(request));
    return;
  }

  // Handle other requests (CSS, JS, images)
  event.respondWith(handleDynamicRequest(request));
});

// Cache-first strategy for static assets
async function handleStaticRequest(request) {
  try {
    const cachedResponse = await caches.match(request);
    if (cachedResponse) {
      return cachedResponse;
    }

    const networkResponse = await fetch(request);
    const cache = await caches.open(STATIC_CACHE);
    cache.put(request, networkResponse.clone());

    return networkResponse;
  } catch (error) {
    console.error('Static request failed:', error);

    // Return offline fallback for HTML requests
    if (request.headers.get('accept').includes('text/html')) {
      return new Response(
        `<!DOCTYPE html>
        <html>
        <head>
          <title>Bytewise - Offline</title>
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <style>
            body { font-family: system-ui, sans-serif; text-align: center; padding: 2rem; color: #334155; }
            .offline { max-width: 400px; margin: 2rem auto; }
            .icon { font-size: 4rem; margin-bottom: 1rem; }
            .title { font-size: 1.5rem; font-weight: bold; margin-bottom: 1rem; }
            .message { margin-bottom: 2rem; color: #64748b; }
            .retry { background: #7dd3fc; color: white; border: none; padding: 0.75rem 1.5rem; border-radius: 0.5rem; cursor: pointer; }
          </style>
        </head>
        <body>
          <div class="offline">
            <div class="icon">🍎</div>
            <div class="title">Bytewise</div>
            <div class="message">You're offline. Please check your connection and try again.</div>
            <button class="retry" onclick="location.reload()">Retry</button>
          </div>
        </body>
        </html>`,
        { headers: { 'Content-Type': 'text/html' } }
      );
    }

    throw error;
  }
}

// Network-first strategy for API requests with fallback
async function handleApiRequest(request) {
  try {
    const networkResponse = await fetch(request);

    // Cache successful API responses
    if (networkResponse.ok) {
      const cache = await caches.open(API_CACHE);
      cache.put(request, networkResponse.clone());
    }

    return networkResponse;
  } catch (error) {
    console.log('Network failed, trying cache for:', request.url);

    // Try to return cached version
    const cachedResponse = await caches.match(request);
    if (cachedResponse) {
      return cachedResponse;
    }

    // Return offline indicator for critical API calls
    if (request.url.includes('/api/auth/user')) {
      return new Response(JSON.stringify({ offline: true }), {
        headers: { 'Content-Type': 'application/json' }
      });
    }

    throw error;
  }
}

// Stale-while-revalidate strategy for dynamic content
async function handleDynamicRequest(request) {
  const cache = await caches.open(DYNAMIC_CACHE);
  const cachedResponse = await cache.match(request);

  const fetchPromise = fetch(request).then(networkResponse => {
    cache.put(request, networkResponse.clone());
    return networkResponse;
  }).catch(() => cachedResponse);

  return cachedResponse || fetchPromise;
}

// Handle background sync for offline actions
self.addEventListener('sync', event => {
  console.log('🔄 Background sync triggered:', event.tag);

  if (event.tag === 'meal-sync') {
    event.waitUntil(syncOfflineMeals());
  }
});

// Sync offline meal logs when connection is restored
async function syncOfflineMeals() {
  try {
    // Get offline meal data from IndexedDB if implemented
    console.log('📤 Syncing offline meal data...');
    // Implementation would depend on offline storage strategy
  } catch (error) {
    console.error('Failed to sync offline meals:', error);
  }
}

// Handle push notifications (future enhancement)
self.addEventListener('push', event => {
  if (!event.data) return;

  const data = event.data.json();
  const options = {
    body: data.body || 'New nutrition insight available!',
    icon: '/icon-192.svg',
    badge: '/icon-192.svg',
    tag: 'bytewise-notification',
    requireInteraction: false,
    actions: [
      {
        action: 'open',
        title: 'Open App'
      },
      {
        action: 'dismiss',
        title: 'Dismiss'
      }
    ]
  };

  event.waitUntil(
    self.registration.showNotification(data.title || 'Bytewise', options)
  );
});

// Handle notification clicks
self.addEventListener('notificationclick', event => {
  event.notification.close();

  if (event.action === 'open' || !event.action) {
    event.waitUntil(
      clients.openWindow('/')
    );
  }
});

console.log('🍎 Bytewise Service Worker loaded successfully');

