  // Alternative endpoint for calculator (for compatibility)
  app.post('/api/foods/calculate', async (req, res) => {
    try {
      const { ingredients } = req.body;

      if (!ingredients) {
        return res.status(400).json({ 
          error: 'Missing required field: ingredients' 
        });
