.slide-button {
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
}

.slide-button::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  transition: left 0.6s ease;
}

.slide-button:hover::before {
  left: 100%;
}

