/**
 * Bytewise Typography System - Brand Guidelines Compliant
 * Primary: League Spartan (headings, brand elements)
 * Secondary: Work Sans (subheadings, labels, buttons)
 * Body: Quicksand (body text, inputs)
 * MOBILE: All inputs minimum 16px to prevent auto-zoom
 * MOBILE-OPTIMIZED: Responsive sizing for better horizontal fit
 */
@layer base {
  :where(:not(:has([class*=" text-"]), :not(:has([class^="text-"])))) {
    h1 {
      font-size: 1.75rem; /* Reduced from 2rem for mobile fit */
      font-weight: 700;
      line-height: 1.1; /* Tighter line height */
      letter-spacing: -0.025em; /* Slight compression */
      font-family: 'League Spartan', sans-serif;
    }

    h2 {
      font-size: 1.375rem; /* Reduced from 1.5rem */
      font-weight: 600;
      line-height: 1.2; /* Tighter line height */
      letter-spacing: -0.015em;
      font-family: 'League Spartan', sans-serif;
    }

    h3 {
      font-size: 1.125rem; /* Reduced from 1.25rem */
      font-weight: 600;
      line-height: 1.3; /* Tighter line height */
      letter-spacing: -0.01em;
      font-family: 'Work Sans', sans-serif;
    }

    h4 {
      font-size: 1rem; /* Reduced from 1.125rem */
      font-weight: 500;
      line-height: 1.4;
      letter-spacing: -0.005em;
      font-family: 'Work Sans', sans-serif;
    }

    h5 {
      font-size: 0.875rem; /* Reduced from 1rem */
      font-weight: 500;
      line-height: 1.4;
      font-family: 'Work Sans', sans-serif;
    }

    h6 {
      font-size: 0.75rem; /* Reduced from 0.875rem */
      font-weight: 500;
      line-height: 1.4;
      font-family: 'Work Sans', sans-serif;
    }

    p {
      font-size: 0.875rem; /* Reduced from 1rem for mobile */
      font-weight: 400;
      line-height: 1.5; /* Slightly tighter */
      font-family: 'Quicksand', sans-serif;
    }

    label {
      font-size: 0.75rem; /* Reduced from 0.875rem */
      font-weight: 500;
      line-height: 1.4;
      font-family: 'Work Sans', sans-serif;
    }

    button {
      font-size: max(16px, 0.875rem); /* Minimum 16px for mobile, but smaller default */
      font-weight: 500;
      line-height: 1.4; /* Tighter line height */
      letter-spacing: 0.01em; /* Slight spacing for readability */
      font-family: 'Work Sans', sans-serif;
    }

    input {
      font-size: max(16px, 1rem) !important; /* Critical: Minimum 16px prevents mobile zoom */
      font-weight: 400;
      line-height: 1.4; /* Slightly tighter */
      font-family: 'Quicksand', sans-serif;
    }

    textarea {
      font-size: max(16px, 1rem) !important; /* Critical: Minimum 16px prevents mobile zoom */
      font-weight: 400;
      line-height: 1.4; /* Slightly tighter */
      font-family: 'Quicksand', sans-serif;
    }

    select {
      font-size: max(16px, 1rem) !important; /* Critical: Minimum 16px prevents mobile zoom */
      font-weight: 400;
      line-height: 1.4; /* Slightly tighter */
      font-family: 'Quicksand', sans-serif;
    }

    /* Brand Logo Typography */
    .brand-logo {
      font-family: 'League Spartan', sans-serif;
      font-weight: 700;
      color: var(--pastel-blue);
    }

    .brand-tagline {
      font-family: 'League Spartan', sans-serif;
      font-weight: 400;
      color: var(--foreground);
    }
  }

  /* Mobile-specific typography adjustments */
  @media screen and (max-width: 640px) {
    :where(:not(:has([class*=" text-"]), :not(:has([class^="text-"])))) {
      h1 {
        font-size: 1.5rem; /* Even smaller on mobile */
        line-height: 1.1;
        letter-spacing: -0.02em;
