      h2 {
        font-size: 1.25rem;
        line-height: 1.2;
        letter-spacing: -0.015em;
      }

      h3 {
        font-size: 1rem;
        line-height: 1.3;
        letter-spacing: -0.01em;
      }

      p {
        font-size: 0.8125rem; /* 13px for very tight mobile layouts */
        line-height: 1.5;
      }

      label {
        font-size: 0.6875rem; /* 11px for compact labels */
        line-height: 1.4;
      }
    }
  }
}

