  background: transparent;
}

.hover-scroll-container:hover .hover-scroll-area::-webkit-scrollbar-thumb,
.hover-scroll-area:focus-within::-webkit-scrollbar-thumb {
  opacity: 0.6;
}

.hover-scroll-item {
  scroll-margin: 8px;
  scroll-snap-align: start;
  transition: all 0.2s ease;
  min-height: 44px;
  position: relative;
}

.hover-scroll-item * {
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
}

/* Recipe Builder Drag States */
.scroll-disabled {
  overflow: hidden !important;
  scroll-behavior: auto !important;
}

.scroll-disabled::-webkit-scrollbar-thumb {
  opacity: 0.2 !important;
}

.recipe-builder-dragging [data-recipe-builder] .ingredients-scroll-area {
  user-select: none;
  -webkit-user-select: none;
  pointer-events: auto;
}

.recipe-builder-dragging [data-recipe-builder] .ingredients-scroll-area * {
  pointer-events: none;
}

