/* Bytewise Brand Spacing System - Mobile-First Ultra-Tight Layout */
:root {
  --spacing-micro: 0.0625rem; /* 1px - Ultra tight */
  --spacing-xs: 0.125rem;     /* 2px - Extra tight */
  --spacing-sm: 0.25rem;      /* 4px - Tight */
  --spacing-md: 0.375rem;     /* 6px - Compact (reduced from 8px) */
  --spacing-lg: 0.5rem;       /* 8px - Small (reduced from 12px) */
  --spacing-xl: 0.75rem;      /* 12px - Medium (reduced from 16px) */
  --spacing-2xl: 1rem;        /* 16px - Large (reduced from 20px) */
  --spacing-3xl: 1.25rem;     /* 20px - Extra large (reduced from 24px) */
  --spacing-4xl: 1.5rem;      /* 24px - Maximum (reduced from 32px) */

  /* Mobile-specific spacing overrides */
  --mobile-spacing-xs: 0.125rem;  /* 2px */
  --mobile-spacing-sm: 0.25rem;   /* 4px */
  --mobile-spacing-md: 0.375rem;  /* 6px */
  --mobile-spacing-lg: 0.5rem;    /* 8px */
  --mobile-spacing-xl: 0.75rem;   /* 12px */

  /* Component-specific spacing */
  --button-padding-x: 0.75rem;    /* 12px horizontal */
  --button-padding-y: 0.5rem;     /* 8px vertical */
  --card-padding: 0.75rem;        /* 12px card padding */
  --input-padding: 0.5rem;        /* 8px input padding */
}

