}

/* Bytewise Brand Animations */
@keyframes slideIn {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes scaleIn {
  from {
    transform: scale(0.9);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes heroSlideUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Enhanced Notification System Animations */
@keyframes notificationSlideIn {
  from {
    opacity: 0;
    transform: translateY(50px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes notificationSlideOut {
  from {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateX(300px) scale(0.95);
  }
}

@keyframes notificationBounceIn {
  0% {
    opacity: 0;
    transform: translateY(50px) scale(0.8);
  }
  60% {
    opacity: 1;
    transform: translateY(-5px) scale(1.05);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes notificationPulse {
  0%, 100% {
    opacity: 0.6;
  }
  50% {
    opacity: 1;
  }
}

@keyframes progressSlide {
  from {
    width: 100%;
  }
  to {
    width: 0%;
  }
}

@keyframes notificationGlow {
  0%, 100% {
    box-shadow: 0 4px 12px rgba(168, 218, 220, 0.2);
  }
  50% {
    box-shadow: 0 8px 24px rgba(168, 218, 220, 0.4);
  }
}

@keyframes floatingAccent {
  0%, 100% {
    transform: translateY(0);
    opacity: 0.6;
  }
  50% {
    transform: translateY(-2px);
    opacity: 1;
  }
}

.animate-slide-in {
  animation: slideIn 0.3s ease-out;
}

.animate-fade-in {
  animation: fadeIn 0.5s ease-out;
}

.animate-scale-in {
  animation: scaleIn 0.3s ease-out;
}

.animate-hero-slide-up {
  animation: heroSlideUp 0.6s ease-out;
}

.animate-notification-slide-in {
  animation: notificationSlideIn 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.animate-notification-slide-out {
  animation: notificationSlideOut 0.3s cubic-bezier(0.55, 0.06, 0.68, 0.19);
}

.animate-notification-bounce-in {
  animation: notificationBounceIn 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.animate-notification-pulse {
