/* Recipe Builder Enhanced Scroll Styles */
[data-recipe-builder] .hover-scroll-area {
  scrollbar-width: thin;
  scrollbar-color: var(--primary) transparent;
  scroll-behavior: smooth;
  overscroll-behavior: contain;
  transition: all 0.2s ease;
}

.hover-scroll-area::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.hover-scroll-area::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.05);
  border-radius: 3px;
}

.hover-scroll-area::-webkit-scrollbar-thumb {
  background: var(--primary);
  border-radius: 3px;
  opacity: 0.4;
  transition: opacity 0.2s ease;
}

.hover-scroll-area::-webkit-scrollbar-thumb:hover {
  opacity: 0.8;
  background: var(--pastel-blue-dark);
}

.hover-scroll-area::-webkit-scrollbar-corner {
  background: transparent;
}

.hover-scroll-container:hover .hover-scroll-area::-webkit-scrollbar-thumb,
.hover-scroll-area:focus-within::-webkit-scrollbar-thumb {
  opacity: 0.6;
}

.hover-scroll-item {
  scroll-margin: 8px;
  scroll-snap-align: start;
  transition: all 0.2s ease;
  min-height: 44px;
  position: relative;
}

.hover-scroll-item * {
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
}

/* Recipe Builder Drag States */
.scroll-disabled {
  overflow: hidden !important;
  scroll-behavior: auto !important;
}

.scroll-disabled::-webkit-scrollbar-thumb {
  opacity: 0.2 !important;
}

.recipe-builder-dragging [data-recipe-builder] .ingredients-scroll-area {
  user-select: none;
  -webkit-user-select: none;
  pointer-events: auto;
}

.recipe-builder-dragging [data-recipe-builder] .ingredients-scroll-area * {
  pointer-events: none;
}

.recipe-builder-dragging [data-recipe-builder] .ingredients-scroll-area .dragging-item {
  pointer-events: auto;
}

.recipe-builder-dragging [data-meal-category] {
  pointer-events: auto;
}

.recipe-builder-dragging [data-meal-category] * {
  pointer-events: none;
}

.recipe-builder-dragging [data-meal-category] .dragging-item {
  pointer-events: auto;
}

.dragging-item {
  position: relative;
  z-index: 1000 !important;
  box-shadow: 0 10px 25px rgba(168, 218, 220, 0.4) !important;
  transform: rotate(2deg) scale(1.05) !important;
  transition: none !important;
  pointer-events: auto !important;
}

[data-recipe-builder] .group.cursor-grab {
  cursor: grab;
  -webkit-user-drag: element;
}

[data-recipe-builder] .group.cursor-grab:active {
  cursor: grabbing;
}

.recipe-builder-dragging [data-recipe-builder].drag-enabled {
  overflow: visible !important;
}

.recipe-builder-dragging [data-recipe-builder].drag-enabled * {
  pointer-events: none;
}

.recipe-builder-dragging [data-recipe-builder].drag-enabled .dragging-item {
  pointer-events: auto !important;
}

.recipe-builder-dragging [data-recipe-builder].drag-enabled .group {
  pointer-events: auto;
}

.drag-feedback-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 30;
  pointer-events: none;
  background: rgba(168, 218, 220, 0.05);
  backdrop-filter: blur(1px);
  transition: all 0.2s ease;
}

/* Mobile Scroll Snap */
