/* Recipe Builder Ingredients Library Enhancements */
[data-recipe-builder] .ingredients-scroll-area {
  position: relative;
  isolation: isolate;
}

[data-recipe-builder] .ingredients-scroll-area::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 12px;
  background: linear-gradient(to bottom, var(--background) 60%, transparent);
  pointer-events: none;
  z-index: 2;
  opacity: 0;
  transition: opacity 0.3s ease;
}

[data-recipe-builder] .ingredients-scroll-area::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 12px;
  background: linear-gradient(to top, var(--background) 60%, transparent);
  pointer-events: none;
  z-index: 2;
  opacity: 0;
  transition: opacity 0.3s ease;
}

[data-recipe-builder] .ingredients-scroll-area:hover::before,
[data-recipe-builder] .ingredients-scroll-area:hover::after,
[data-recipe-builder] .ingredients-scroll-area.scrolling::before,
[data-recipe-builder] .ingredients-scroll-area.scrolling::after {
  opacity: 1;
}

.recipe-builder-dragging [data-recipe-builder] .ingredients-scroll-area::before,
.recipe-builder-dragging [data-recipe-builder] .ingredients-scroll-area::after {
  opacity: 0 !important;
}

/* Scroll Indicator Animation */
@keyframes scrollPulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 0.8; }
