      {/* Day Summary Footer */}
      {dailyTotals.meals > 0 && (
        <div className="mt-6 p-4 bg-gradient-to-r from-gray-50 to-slate-50 rounded-xl border border-gray-200">
          <div className="flex items-center justify-between text-sm">
            <div className="flex items-center gap-4">
