  const renderSignIn = () => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isSignUp, setIsSignUp] = useState(false);
    const [isResetPassword, setIsResetPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const { toast } = useToast();
    const { refetch } = useAuth();

    const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);

      try {
        if (isResetPassword) {
          // Password reset flow
          const { error } = await supabase.auth.resetPasswordForEmail(email, {
            redirectTo: `${window.location.origin}/reset-password`,
          });

          if (error) throw error;

          toast({
            title: "Check your email",
            description: "We've sent you a password reset link. Please check your email.",
          });
          setIsResetPassword(false);
        } else if (isSignUp) {
          // Sign up flow with email verification requirement
          const { data, error } = await supabase.auth.signUp({
            email,
            password,
            options: {
              emailRedirectTo: window.location.origin,
              data: {
                email_verified: false
              }
            }
          });

          if (error) throw error;

          if (data?.user?.identities?.length === 0) {
            toast({
              title: "Account exists",
              description: "An account with this email already exists. Please sign in instead.",
              variant: "destructive",
            });
            setIsSignUp(false);
          } else {
            toast({
              title: "Verify your email",
              description: "We've sent you a verification link. You must verify your email before you can sign in.",
            });
            setIsSignUp(false);
            setEmail('');
            setPassword('');
          }
        } else {
          // Sign in flow with email verification check
          const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password,
          });

          if (error) {
            // Check if error is due to unverified email
            if (error.message.includes('Email not confirmed') || error.message.includes('email_not_confirmed')) {
              toast({
                title: "Email not verified",
                description: "Please verify your email before signing in. Check your inbox for the verification link.",
                variant: "destructive",
              });
              return;
            }
            throw error;
          }

          // Additional check for email verification
          if (data?.user && !data.user.email_confirmed_at) {
            await supabase.auth.signOut();
            toast({
              title: "Email not verified",
              description: "Please verify your email before signing in. Check your inbox for the verification link.",
              variant: "destructive",
            });
            return;
          }

          toast({
            title: "Welcome back!",
            description: "You've successfully signed in.",
          });

          // Refetch user data and reload
          await refetch();
          window.location.reload();
        }
      } catch (error: any) {
        toast({
          title: "Error",
          description: error.message || "Something went wrong. Please try again.",
          variant: "destructive",
        });
      } finally {
        setIsLoading(false);
      }
    };

    const handleResendVerification = async () => {
      if (!email) {
        toast({
          title: "Email required",
          description: "Please enter your email address to resend verification.",
          variant: "destructive",
        });
        return;
      }

      setIsLoading(true);
      try {
        const { error } = await supabase.auth.resend({
          type: 'signup',
          email: email,
        });

        if (error) throw error;

        toast({
          title: "Verification email sent",
          description: "Please check your inbox for the verification link.",
        });
      } catch (error: any) {
        toast({
          title: "Error",
          description: error.message || "Failed to resend verification email.",
          variant: "destructive",
        });
      } finally {
        setIsLoading(false);
      }
    };

    return (
      <div className="space-y-0">
        <HeroSection
          title="Welcome to"
          subtitle="Nutrition"
          description="Sign in to start tracking your nutrition journey"
          buttonText="Get Started"
          onButtonClick={() => {
            const signInCard = document.querySelector('.bg-white\\/10');
            if (signInCard) {
              signInCard.scrollIntoView({ behavior: 'smooth' });
            }
          }}
        />

        {/* Content Section - Completely Separate and Underneath */}
        <div className="px-6 py-3 content-section">
          {/* Sign In Component */}
          <Card className="bg-gradient-to-br from-amber-50 to-amber-100 backdrop-blur-md p-6">
            <h3 className="text-2xl font-bold mb-6 text-center">
              {isResetPassword ? 'Reset Password' : isSignUp ? 'Create Account' : 'Sign In'}
            </h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <Input
                type="email"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="h-12 bg-amber-50/90 border-amber-400 text-gray-900 placeholder-gray-600"
                required
                disabled={isLoading}
              />
              {!isResetPassword && (
                <Input
                  type="password"
                  placeholder="Password (min 6 characters)"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="h-12 bg-amber-50/90 border-amber-400 text-gray-900 placeholder-gray-600"
                  required
                  disabled={isLoading}
                  minLength={6}
                />
              )}
              <Button 
                type="submit"
                className="w-full bg-amber-500 hover:bg-amber-600 text-white font-bold h-12 rounded-xl btn-hero-enhanced"
                disabled={isLoading}
              >
                {isLoading ? 'Loading...' : 
                 isResetPassword ? 'Send Reset Link' : 
                 isSignUp ? 'Create Account' : 'Sign In'}
              </Button>

              {/* Additional options */}
              <div className="space-y-2">
                {!isResetPassword && !isSignUp && (
                  <div className="text-center">
                    <Button 
                      type="button"
                      variant="link" 
                      className="text-gray-600 hover:text-gray-900 text-sm"
                      onClick={() => setIsResetPassword(true)}
                      disabled={isLoading}
                    >
                      Forgot password?
                    </Button>
                  </div>
                )}

                <div className="text-center">
                  <Button 
                    type="button"
                    variant="link" 
                    className="text-gray-600 hover:text-gray-900"
                    onClick={() => {
                      setIsSignUp(!isSignUp && !isResetPassword);
                      setIsResetPassword(false);
                    }}
                    disabled={isLoading}
                  >
                    {isResetPassword ? 'Back to sign in' : 
                     isSignUp ? 'Already have an account? Sign in' : 
                     "Don't have an account? Sign up"}
                  </Button>
                </div>

                {isSignUp && (
                  <div className="text-center">
                    <Button 
                      type="button"
                      variant="link" 
                      className="text-gray-600 hover:text-gray-900 text-sm"
                      onClick={handleResendVerification}
                      disabled={isLoading || !email}
                    >
                      Resend verification email
                    </Button>
                  </div>
                )}
              </div>

              {isSignUp && (
                <div className="mt-4 p-3 bg-blue-500/20 rounded-lg">
                  <p className="text-xs text-gray-200 text-center">
                    By creating an account, you must verify your email address before you can sign in.
                  </p>
                </div>
              )}
            </form>
          </Card>
        </div>
      </div>
    );
  };

