      const canvas = createChartCanvas(600, 400);

      const chart = new Chart(canvas, {
        type: 'bar',
        data: {
          labels: waterData.map(d => new Date(d.date).toLocaleDateString()),
          datasets: [{
            label: 'Water Intake (Glasses)',
            data: waterData.map(d => d.glasses || d.amount || 0),
            backgroundColor: 'rgba(59, 130, 246, 0.7)', // blue for water
            borderColor: '#3b82f6',
            borderWidth: 2,
            borderRadius: 6,
          }]
        },
        options: {
          responsive: false,
          animation: false,
          plugins: {
            legend: {
              labels: {
                color: '#92400e',
                font: { size: 14, family: 'Arial' }
              }
            },
            title: {
              display: true,
              text: 'Weekly Water Intake',
              color: '#78350f',
              font: { size: 18, weight: 'bold', family: 'Arial' }
            }
          },
          scales: {
            y: {
              beginAtZero: true,
              ticks: { color: '#92400e' },
              grid: { color: 'rgba(146, 64, 14, 0.1)' },
              title: {
                display: true,
                text: 'Glasses per Day',
                color: '#92400e'
              }
            },
            x: {
              ticks: { color: '#92400e', maxRotation: 45 },
              grid: { color: 'rgba(146, 64, 14, 0.1)' }
            }
          }
        }
      });

      setTimeout(() => {
        try {
          const dataUrl = canvas.toDataURL('image/png');
          chart.destroy();
          resolve(dataUrl);
        } catch (error) {
          chart.destroy();
          reject(error);
        }
      }, 500);
    } catch (error) {
      reject(error);
    }
  });
}

