          </p>

          <Button
            onClick={onClose}
            className="bg-gradient-to-r from-green-500 to-green-600 hover:from-green-600 hover:to-green-700 text-white"
          >
            Awesome!
          </Button>
        </div>
      </Card>
    </div>
  );
}

