          {/* Annual Plans Notice */}
          <div className="text-center bg-amber-100/50 rounded-lg p-4 border border-amber-200">
            <p className="text-sm text-gray-700">
              <Sparkles className="w-4 h-4 inline mr-1 text-amber-500" />
