/**
 * Notification Dropdown Component
 * 
 * Data management card styled notification popup for header bell icon
 * Features comprehensive notification display with proper sizing
 */

import React, { useState, useEffect } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { 
  Bell,
  CheckCircle,
  Info,
  AlertTriangle,
  XCircle,
  Trash2,
  Calendar,
  Target,
  Flame,
  TrendingUp,
  X,
  Settings,
  Clock
} from 'lucide-react';

interface NotificationItem {
  id: string;
  type: 'success' | 'info' | 'warning' | 'error' | 'achievement';
  title: string;
  message: string;
  timestamp: Date;
  read: boolean;
  icon?: any;
}

interface NotificationDropdownProps {
  isOpen: boolean;
  onClose: () => void;
  notifications: NotificationItem[];
  onMarkAsRead: (id: string) => void;
  onMarkAllAsRead: () => void;
  onDeleteNotification: (id: string) => void;
  onNavigate?: (page: string, section?: string) => void;
}

export function NotificationDropdown({
  isOpen,
  onClose,
  notifications,
  onMarkAsRead,
  onMarkAllAsRead,
  onDeleteNotification,
  onNavigate
}: NotificationDropdownProps) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted || !isOpen) return null;

  const getNotificationIcon = (type: string, customIcon?: any) => {
    if (customIcon) return customIcon;

    switch (type) {
      case 'success': return CheckCircle;
      case 'warning': return AlertTriangle;
      case 'error': return XCircle;
      case 'achievement': return Target;
      default: return Info;
    }
  };

  const getNotificationColor = (type: string) => {
    switch (type) {
      case 'success': return 'text-green-600';
      case 'warning': return 'text-yellow-600';
      case 'error': return 'text-red-600';
      case 'achievement': return 'text-blue-600';
      default: return 'text-blue-600';
    }
  };

  const getBadgeVariant = (type: string) => {
    switch (type) {
      case 'success': return 'default';
      case 'warning': return 'secondary';
      case 'error': return 'destructive';
      case 'achievement': return 'default';
      default: return 'secondary';
    }
  };

  return (
    <div className="absolute top-full right-0 mt-2 w-80 max-h-96 z-50">
      <Card className="p-4 bg-white/80 backdrop-blur-sm border-0 shadow-lg max-h-96 overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Bell className="w-5 h-5 text-blue-600" />
            <h3 className="text-lg font-bold text-gray-900">Notifications</h3>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="h-8 w-8 p-0"
          >
            <X className="w-4 h-4" />
          </Button>
        </div>

        {/* Summary Stats - Data Management Card Style */}
        <div className="mb-4">
          <div className="flex items-center justify-between mb-3">
            <div>
              <h4 className="font-medium text-gray-900">Notification Summary</h4>
              <p className="text-sm text-gray-600">Stay updated with your nutrition progress</p>
            </div>
            <Badge variant="outline" className="text-blue-600 border-blue-600">
              <Bell className="w-3 h-3 mr-1" />
              {notifications.filter(n => !n.read).length} New
            </Badge>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <div className="text-center p-2 bg-blue-50 rounded-lg">
              <Bell className="w-4 h-4 mx-auto text-blue-600 mb-1" />
              <p className="text-xs text-gray-600">Total</p>
              <p className="font-bold text-gray-900 text-sm">{notifications.length}</p>
            </div>
            <div className="text-center p-2 bg-green-50 rounded-lg">
              <CheckCircle className="w-4 h-4 mx-auto text-green-600 mb-1" />
              <p className="text-xs text-gray-600">Read</p>
              <p className="font-bold text-gray-900 text-sm">{notifications.filter(n => n.read).length}</p>
            </div>
            <div className="text-center p-2 bg-orange-50 rounded-lg">
              <AlertTriangle className="w-4 h-4 mx-auto text-orange-600 mb-1" />
              <p className="text-xs text-gray-600">Unread</p>
              <p className="font-bold text-gray-900 text-sm">{notifications.filter(n => !n.read).length}</p>
            </div>
          </div>
        </div>

        <Separator className="mb-4" />

        {/* Action Buttons - Data Management Card Style */}
        {notifications.length > 0 && (
