            </Button>

            <Separator />

            {onLogout && (
              <Button 
                variant="destructive" 
                className="slide-button w-full justify-start"
                onClick={onLogout}
              >
                <LogOut className="mr-3" size={16} />
                Sign Out
              </Button>
            )}
          </div>
        </Card>
      </div>
    </div>
  );
}

