/**
 * Image with Fallback Component
 * 
 * Handles image loading with fallback support for food images
 * Provides consistent image display across the app
 */

import { useState } from 'react';
import { ImageOff } from 'lucide-react';

interface ImageWithFallbackProps {
  src: string;
  alt: string;
  className?: string;
  fallbackClassName?: string;
  width?: number;
  height?: number;
}

export function ImageWithFallback({ 
  src, 
  alt, 
  className = '', 
  fallbackClassName = '',
  width,
  height 
}: ImageWithFallbackProps) {
  const [imageError, setImageError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const handleImageError = () => {
    setImageError(true);
    setIsLoading(false);
  };

  const handleImageLoad = () => {
    setIsLoading(false);
  };

  if (imageError) {
    return (
      <div 
        className={`flex items-center justify-center bg-gray-100 ${fallbackClassName || className}`}
        style={{ width, height }}
      >
        <div className="text-center">
          <ImageOff className="w-8 h-8 text-gray-400 mx-auto mb-2" />
          <p className="text-xs text-gray-500">{alt}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="relative">
      {isLoading && (
        <div 
          className={`absolute inset-0 flex items-center justify-center bg-gray-100 animate-pulse ${className}`}
          style={{ width, height }}
        >
          <div className="w-6 h-6 border-2 border-gray-300 border-t-blue-500 rounded-full animate-spin" />
        </div>
      )}
      <img
        src={src}
        alt={alt}
        className={`${className} ${isLoading ? 'opacity-0' : 'opacity-100'} transition-opacity duration-300`}
        onError={handleImageError}
        onLoad={handleImageLoad}
        width={width}
        height={height}
      />
    </div>
  );
}

import { useState } from 'react';
import { Food } from '@shared/schema';
import { useDragDrop } from './DragDropProvider';
import { Card } from './ui/card';
import { Badge } from './ui/badge';

interface IngredientCardProps {
  food: Food;
  onClick?: () => void;
  draggable?: boolean;
}

export function IngredientCard({ food, onClick, draggable = true }: IngredientCardProps) {
  const { startDrag, endDrag } = useDragDrop();
  const [isDragging, setIsDragging] = useState(false);

  const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    if (!draggable) return;

    const element = e.currentTarget;
    setIsDragging(true);
    element.classList.add('dragging');
    startDrag(food, element);
  };

  const handleTouchEnd = () => {
    if (!draggable) return;

    setIsDragging(false);
    endDrag();
  };

  const handleClick = () => {
    if (!isDragging && onClick) {
      onClick();
    }
  };

  return (
    <Card 
      className={`p-3 touch-target transition-all ${
        draggable ? 'cursor-grab active:cursor-grabbing' : ''
      } ${isDragging ? 'scale-105 shadow-lg' : 'hover:shadow-md'}`}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onClick={handleClick}
    >
      <div className="flex items-center space-x-3">
        <div className="flex-1 min-w-0">
          <div className="flex items-center space-x-2">
            <h4 className="font-medium text-sm truncate">{food.name}</h4>
            {food.verified && (
              <Badge variant="secondary" className="text-xs">
                ✓
              </Badge>
            )}
          </div>
          {food.brand && (
            <p className="text-xs text-muted-foreground">{food.brand}</p>
          )}
          <p className="text-xs text-muted-foreground">
            {food.servingSize} • {Math.round(Number(food.calories))} cal
          </p>
        </div>

        <div className="text-right">
          <div className="text-sm font-medium">
            {Math.round(Number(food.calories))} cal
          </div>
          <div className="text-xs text-muted-foreground">
            {Math.round(Number(food.protein))}g protein
          </div>
        </div>
      </div>
    </Card>
  );
}

