          icon: Calendar,
          value: totalPlannedMeals,
          label: "meals planned",
          iconColor: "green-400"
        }}
        progressRing={{
          percentage: Math.min((totalPlannedMeals / 21) * 100, 100),
          color: "#a8dadc",
          label: "week"
        }}
      />

      {/* Main Content */}
      <div className="px-4 space-y-6">
        {/* Week Navigation */}
        <Card className="p-4">
          <div className="flex items-center justify-between mb-4">
